layer.css:
[data-ryt="pitch"] { color: #a08107; background-image: repeating-linear-gradient(45deg, rgb(26, 36, 32), rgb(26, 36, 32) 10px, rgb(15, 24, 20) 10px, rgb(15, 24, 20) 20px); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-left: 4px solid rgb(255, 204, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 13px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 204, 0); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 16px; padding-bottom: 16px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-muted); border-top: 1px solid rgb(45, 61, 53); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #07a044; border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgba(0, 255, 100, 0.4); text-decoration-thickness: auto; text-underline-offset: 2.6px; text-shadow: rgba(0, 255, 100, 0.3) 0px 0px 5px; transition: 0.3s }
[data-ryt="brand"] { color: #07a044; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: 0.5px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 255, 102); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(0, 255, 100, 0.3) 0px 0px 5px; transition: 0.3s }
[data-ryt="nav"] a { color: #07a044; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 13px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 255, 102); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(0, 255, 100, 0.3) 0px 0px 5px; padding-top: 0px; padding-right: 0px; padding-bottom: 3.2px; padding-left: 0px; transition: 0.3s }
[data-ryt="review"] { color: #7d8483; font-family: var(--ryt-font-heading); font-size: 13px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(197, 209, 207); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 11.7px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: #07a044; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: 0.5px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 255, 102); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(0, 255, 100, 0.3) 0px 0px 5px; transition: 0.3s }
body { background-image: linear-gradient(rgb(13, 20, 16) 0%, rgb(26, 36, 32) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: #cf7303; border-left: 4px solid rgb(0, 255, 102); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: 0.5px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 140, 0); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: rgba(255, 140, 0, 0.5) 0px 0px 10px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-shadow: rgba(255, 140, 0, 0.6) 0px 0px 10px }
[data-ryt="nav"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-shadow: rgba(255, 140, 0, 0.6) 0px 0px 10px }
[data-ryt="brand"]:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-shadow: rgba(255, 140, 0, 0.6) 0px 0px 10px }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-shadow: rgba(255, 140, 0, 0.6) 0px 0px 10px; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: rgba(255, 140, 0, 0.6) }
